class Solution {
    public int alternatingSubarray(int[] nums){
        int current=1,answer=-1;
        for(int i=1;i<nums.length;i++){
            int difference=nums[i]-nums[i-1];
            if(current>=2&&difference==(current%2==0?-1:1))current++;
            else current=difference==1?2:1;
            if(current>=2)answer=Math.max(answer,current);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun alternatingSubarray(nums:IntArray):Int{
        var current=1;
        var answer=-1;
        for(i in 1 until nums.size){
            val difference=nums[i]-nums[i-1];
            current=if(current>=2&&difference==if(current%2==0)-1 else 1)current+1 else if(difference==1)2 else 1;
            if(current>=2)answer=maxOf(answer,current)
        };
        return answer
    }
}

